# Parse all questions from the data
questions = []
for line in data_lines:
    if line.startswith('Date:'):
        # Extract the instance/question part
        parts = line.split(' || ')
        if len(parts) >= 3 and parts[2].startswith('Instance:'):
            question_text = parts[2][9:]  # Remove 'Instance: ' prefix
            questions.append(question_text)

print(f"Total questions parsed: {len(questions)}")
print(f"\nFirst 3 questions:")
for i, q in enumerate(questions[:3]):
    print(f"{i+1}. {q[:100]}...")

print(f"\nLast 3 questions:")
for i, q in enumerate(questions[-3:]):
    print(f"{len(questions)-2+i}. {q[:100]}...")
